import datetime
import calendar


def recur(start: str, rule: str, count: int) -> list[str]:
    s = datetime.date.fromisoformat(start)
    toks = rule.split(" ")
    kind = toks[0]
    K = int(toks[1])
    res = []
    limit = datetime.date(3000, 1, 1)

    def add(d):
        if d >= s:
            res.append(d.isoformat())
        return len(res) >= count

    if kind == "DAILY":
        d = s
        while len(res) < count:
            res.append(d.isoformat())
            d += datetime.timedelta(days=K)
        return res

    if kind == "WEEKLY":
        codes = ["MO", "TU", "WE", "TH", "FR", "SA", "SU"]
        days = sorted(codes.index(c) for c in toks[2].split(","))
        wk = s - datetime.timedelta(days=s.weekday())
        while wk < limit:
            for wd in days:
                d = wk + datetime.timedelta(days=wd)
                if add(d):
                    return res
            wk += datetime.timedelta(weeks=K)
        return res

    if kind == "MONTHLY":
        y, m = s.year, s.month
        while datetime.date(y, m, 1) < limit:
            ndays = calendar.monthrange(y, m)[1]
            d = None
            if len(toks) == 3:
                D = int(toks[2])
                if D == -1:
                    d = datetime.date(y, m, ndays)
                elif D <= ndays:
                    d = datetime.date(y, m, D)
            else:
                N = int(toks[2])
                codes = ["MO", "TU", "WE", "TH", "FR", "SA", "SU"]
                wd = codes.index(toks[3])
                matches = [day for day in range(1, ndays + 1)
                           if datetime.date(y, m, day).weekday() == wd]
                if N == -1:
                    d = datetime.date(y, m, matches[-1])
                elif N <= len(matches):
                    d = datetime.date(y, m, matches[N - 1])
            if d is not None and add(d):
                return res
            idx = y * 12 + (m - 1) + K
            y, m = idx // 12, idx % 12 + 1
        return res

    if kind == "YEARLY":
        mm, dd = map(int, toks[2].split("-"))
        y = s.year
        while y < 3000:
            if dd <= calendar.monthrange(y, mm)[1]:
                if add(datetime.date(y, mm, dd)):
                    return res
            y += K
        return res

    return res
